// Authorize (admin/editor, same as publish) and stage the manifest bytes.
const who = $('Manifest Whoami').first().json || {};
const userId = who.user_id ? String(who.user_id).trim() : null;
const FOUNDER = '@collective_boundary730383:hyphae.social';
let roles = {};
try {
  const raw = $('Manifest Fetch Roles').first().json || {};
  const text = typeof raw.data === 'string' ? raw.data : JSON.stringify(raw);
  const parsed = JSON.parse(text);
  const lay = (parsed && parsed.layout) || parsed;
  if (lay && lay.roles && typeof lay.roles === 'object') roles = lay.roles;
} catch (e) {}
const role = userId === FOUNDER ? 'admin' : (userId ? (roles[userId] || null) : null);
const authorized = !!userId && (role === 'admin' || role === 'editor');

const hook = $('Manifest Webhook').first().json;
const body = hook.body && typeof hook.body === 'object' ? hook.body : hook;
const identifier = (String(body.identifier || 'npj-site').replace(/[^A-Za-z0-9._-]/g, '-').replace(/^-+|-+$/g, '').slice(0, 90)) || 'npj-site';
const filename = (String(body.filename || 'manifest.json').replace(/[^A-Za-z0-9._-]/g, '')) || 'manifest.json';
let manifest = body.manifest;
if (typeof manifest === 'string') { try { manifest = JSON.parse(manifest); } catch (e) {} }
const valid = !!(manifest && typeof manifest === 'object' && Array.isArray(manifest.articles));
const content = valid ? JSON.stringify(manifest) : '';
return [{ json: {
  authorized, valid, user_id: userId, role, identifier, filename,
  count: valid ? manifest.articles.length : 0,
  error: !authorized ? 'unauthorized' : (!valid ? 'manifest must be an object with an articles[] array' : null)
}, binary: { data: { data: Buffer.from(content, 'utf8').toString('base64'), mimeType: 'application/json', fileName: filename } } }];

const r = $input.first().json || {};
const built = $('Manifest Authorize').first().json || {};
const status = Number(r.statusCode || 0) || null;
const ok = !r.error && (!status || status < 400);
const url = ok ? ('https://archive.org/download/' + built.identifier + '/' + built.filename) : null;
return [{ json: { ok, statusCode: ok ? 200 : (status || 502), url,
  identifier: built.identifier, filename: built.filename, count: built.count,
  error: ok ? null : ((typeof r.error === 'string' ? r.error : (r.error && r.error.message)) || ('archive.org manifest PUT failed (' + (status || '?') + ')')) } }];
